import type { AgentrackError } from "../core/errors";
import type {
  BlockageInfo,
  CommentId,
  ComputedComment,
  ComputedIssue,
  IndexEntry,
  IssueId,
  IssueStatus,
  UserInfo,
} from "./index";

// ─── Init ───────────────────────────────────────────────────────────

/** Result of initializing a new tracker directory. */
export type InitResult =
  | { result: "OK"; path: string }
  | { result: "ALREADY_INITIALIZED"; path: string };

// ─── Create ─────────────────────────────────────────────────────────

/** Parameters for creating a new issue. */
export interface CreateParams {
  /** The issue title (required). */
  title: string;
  /** Optional description, defaults to "". */
  description?: string;
  /** Optional assignee, defaults to null. */
  assignee?: string;
  /** Optional tags, defaults to []. */
  tags?: string[];
  /** Initial status, defaults to "idea". */
  status?: IssueStatus;
  /** Priority 1-5, defaults to 3. */
  priority?: 1 | 2 | 3 | 4 | 5;
  /** Optional parent issue ID for hierarchy. */
  parentId?: IssueId | null;
  /** Custom file path for the issue (relative to tracker dir). */
  path?: string;
  /** Override author (resolved by auth layer if not provided). */
  author?: string;
}

/** Result of creating a new issue. */
export type CreateResult = { id: IssueId } | AgentrackError;

// ─── Update ─────────────────────────────────────────────────────────

/** Parameters for updating an existing issue. At least one field must be provided. */
export interface UpdateParams {
  /** New title. */
  title?: string;
  /** New description. */
  description?: string;
  /** New status. */
  status?: IssueStatus;
  /** New assignee, or null to clear. */
  assignee?: string | null;
  /** New tags (replaces existing). */
  tags?: string[];
  /** New priority (1-5). */
  priority?: 1 | 2 | 3 | 4 | 5;
  /** New parent ID, null to detach from parent. */
  parentId?: IssueId | null;
  /** Override author (resolved by auth layer if not provided). */
  author?: string;
}

/** Result of updating an issue. */
export type UpdateResult = { result: "OK" } | AgentrackError;

// ─── List ───────────────────────────────────────────────────────────

/** Parameters for listing issues with optional filters. */
export interface ListParams {
  /** Filter by status. "open" = all except closed. */
  status?: IssueStatus | "open";
  /** Filter by assignee name. */
  assignee?: string;
  /** AND filter — issue must have ALL specified tags. */
  tags?: string[];
  /** Filter by parent ID. null = top-level issues only. */
  parentId?: IssueId | null;
}

/** Result of listing issues — sorted by priority ASC, impact DESC, id ASC. */
export type ListResult = IndexEntry[];

// ─── View ───────────────────────────────────────────────────────────

/** Result of viewing an issue's full computed state. */
export type ViewResult = ComputedIssue | AgentrackError;

// ─── Next ───────────────────────────────────────────────────────────

/** Result of the next command — the recommended issue to work on, or no issues available. */
export type NextResult = ComputedIssue | { result: "NO_ISSUES_AVAILABLE"; message: string };

// ─── History ────────────────────────────────────────────────────────

import type { Event } from "./event";

export type { Event };

/** Result of retrieving an issue's raw event history. */
export type HistoryResult = Event[] | AgentrackError;

// ─── Comments ───────────────────────────────────────────────────────

/** Parameters for adding a comment to an issue. */
export interface CommentAddParams {
  /** The comment content. */
  content: string;
  /** Override author (resolved by auth layer if not provided). */
  author?: string;
}

/** Result of adding a comment. */
export type CommentAddResult = { result: "OK"; commentId: CommentId } | AgentrackError;

/** Parameters for updating an existing comment. */
export interface CommentUpdateParams {
  /** The new comment content. */
  content: string;
  /** Override author (resolved by auth layer if not provided). */
  author?: string;
}

/** Result of updating a comment. */
export type CommentUpdateResult = { result: "OK" } | AgentrackError;

/** Parameters for deleting a comment. */
export interface CommentDeleteParams {
  /** Override author (resolved by auth layer if not provided). */
  author?: string;
}

/** Result of deleting a comment. */
export type CommentDeleteResult = { result: "OK" } | AgentrackError;

/** Result of listing comments for an issue. */
export type CommentsListResult = ComputedComment[] | AgentrackError;

// ─── Blockages ──────────────────────────────────────────────────────

/** Parameters for adding blockage dependencies. */
export interface BlockagesAddParams {
  /** IDs of the blocker issues. */
  blockerIds: IssueId[];
  /** Override author (resolved by auth layer if not provided). */
  author?: string;
}

/** Result of adding blockages. */
export type BlockagesAddResult = { result: "OK" } | AgentrackError;

/** Parameters for resolving blockage dependencies. */
export interface BlockagesResolveParams {
  /** IDs of the blocker issues to resolve. */
  blockerIds: IssueId[];
  /** Override author (resolved by auth layer if not provided). */
  author?: string;
}

/** Result of resolving blockages. */
export type BlockagesResolveResult = { result: "OK" } | AgentrackError;

/** Parameters for deleting blockage dependencies. */
export interface BlockagesDeleteParams {
  /** IDs of the blocker issues to delete. */
  blockerIds: IssueId[];
  /** Override author (resolved by auth layer if not provided). */
  author?: string;
}

/** Result of deleting blockages. */
export type BlockagesDeleteResult = { result: "OK" } | AgentrackError;

/** Result of listing blockage info for an issue. */
export type BlockagesListResult = BlockageInfo | AgentrackError;

// ─── Users ──────────────────────────────────────────────────────────

/** Result of registering a new user. */
export type UsersRegisterResult =
  | { result: "OK"; name: string; token: string }
  | { result: "USER_ALREADY_EXISTS"; message: string };

/** Result of listing users — tokens are never included. */
export type UsersListResult = UserInfo[];

/** Result of revoking a user. */
export type UsersRevokeResult = { result: "OK" } | { result: "USER_NOT_FOUND"; message: string };

/** Result of regenerating a user token (self-service only). */
export type UsersRegenerateResult =
  | { result: "OK"; name: string; token: string }
  | { result: "USER_NOT_FOUND"; message: string }
  | { result: "INVALID_TOKEN"; message: string };

// ─── Worktree ────────────────────────────────────────────────────────

/** Result of initializing a git worktree for agentrack data. */
export interface WorktreeInitResult {
  scenario: "fresh" | "join" | "already_initialized";
  path: string;
}

/** Result of pushing agentrack data to remote. */
export interface WorktreeSyncResult {
  synced: boolean;
  commitCount?: number;
  message?: string;
}

/** Result of pulling agentrack data from remote. */
export interface WorktreePullResult {
  updated: boolean;
}

import { Command } from "commander";
import {
  blockagesAddAction,
  blockagesDeleteAction,
  blockagesListAction,
  blockagesResolveAction,
} from "./commands/blockages";
import {
  commentsAddAction,
  commentsDeleteAction,
  commentsListAction,
  commentsUpdateAction,
} from "./commands/comments";
import { createAction } from "./commands/create";
import { historyAction } from "./commands/history";
import { initAction } from "./commands/init";
import { listAction } from "./commands/list";
import { nextAction } from "./commands/next";
import { pullAction } from "./commands/pull";
import { pushAction } from "./commands/push";
import { updateAction } from "./commands/update";
import {
  usersListAction,
  usersRegenerateAction,
  usersRegisterAction,
  usersRevokeAction,
} from "./commands/users";
import { viewAction } from "./commands/view";

/**
 * Create and configure the Commander program.
 */
export function createProgram(): Command {
  const program = new Command();

  program
    .name("agt")
    .description("Issue tracker designed for AI agents — file-backed, event-sourced, git-friendly")
    .version("0.1.0");

  // ─── init ─────────────────────────────────────────────────────────
  program
    .command("init")
    .description("Initialize a new .agentrack/ directory")
    .action(initAction);

  // ─── create ───────────────────────────────────────────────────────
  program
    .command("create <title>")
    .description("Create a new issue")
    .option("--description <string>", "Issue description")
    .option("--assignee <string>", "Assignee name")
    .option("--tags <comma-separated>", "Comma-separated tags")
    .option("--status <status>", 'Issue status (default: "idea")')
    .option("--priority <number>", "Priority 1-5 (default: 3)")
    .option("--parentId <id>", "Parent issue ID")
    .option("--path <string>", "Custom file path for the issue")
    .action(createAction);

  // ─── list ─────────────────────────────────────────────────────────
  program
    .command("list")
    .description("List issues")
    .option(
      "--status <status>",
      'Filter by status (use "open" for non-closed, "closed" for closed)',
    )
    .option("--assignee <string>", "Filter by assignee")
    .option("--tags <comma-separated>", "Comma-separated tags (AND filter)")
    .option("--parentId <id>", 'Filter by parent ID (use "null" for top-level)')
    .action(listAction);

  // ─── next ──────────────────────────────────────────────────────────
  program
    .command("next <userName>")
    .description("Get the recommended next issue to work on for a user")
    .action(nextAction);

  // ─── push ──────────────────────────────────────────────────────────
  program
    .command("push")
    .description("Sync agentrack data to remote")
    .option("--message <string>", "Override auto-generated commit message")
    .action(pushAction);

  // ─── pull ──────────────────────────────────────────────────────────
  program
    .command("pull")
    .description("Sync agentrack data from remote")
    .action(pullAction);

  // ─── view ─────────────────────────────────────────────────────────
  program
    .command("view <issueId>")
    .description("View an issue's full computed state")
    .action(viewAction);

  // ─── update ───────────────────────────────────────────────────────
  program
    .command("update <issueId>")
    .description("Update an existing issue")
    .option("--title <string>", "New title")
    .option("--description <string>", "New description")
    .option("--status <status>", "New status")
    .option("--assignee <string>", "New assignee")
    .option("--tags <comma-separated>", "New tags (replaces existing)")
    .option("--priority <number>", "New priority (1-5)")
    .option("--parentId <id>", 'New parent ID (use "null" to detach)')
    .action(updateAction);

  // ─── history ──────────────────────────────────────────────────────
  program
    .command("history <issueId>")
    .description("View an issue's raw event history")
    .action(historyAction);

  // ─── comments ─────────────────────────────────────────────────────
  const commentsCmd = program.command("comments").description("Manage comments on issues");

  commentsCmd
    .command("add <issueId>")
    .description("Add a comment to an issue")
    .requiredOption("--content <content>", "Comment content")
    .action(commentsAddAction);

  commentsCmd
    .command("update <issueId> <commentId>")
    .description("Update an existing comment")
    .requiredOption("--content <content>", "New comment content")
    .action(commentsUpdateAction);

  commentsCmd
    .command("delete <issueId> <commentId>")
    .description("Delete a comment")
    .action(commentsDeleteAction);

  commentsCmd
    .command("list <issueId>")
    .description("List comments on an issue")
    .action(commentsListAction);

  // ─── users ────────────────────────────────────────────────────────
  const usersCmd = program.command("users").description("Manage users");

  usersCmd
    .command("register <name>")
    .description("Register a new user")
    .action(usersRegisterAction);

  usersCmd.command("list").description("List registered users").action(usersListAction);

  usersCmd.command("revoke <name>").description("Revoke (remove) a user").action(usersRevokeAction);

  usersCmd
    .command("regenerate <name>")
    .description("Regenerate a user's token (self-service only)")
    .action(usersRegenerateAction);

  // ─── blockages ─────────────────────────────────────────────────────
  const blockagesCmd = program.command("blockages").description("Manage issue blockages");

  blockagesCmd
    .command("add <blockedId>")
    .description("Add blockage dependencies to an issue")
    .requiredOption("--by <ids...>", "Blocker issue IDs")
    .action(blockagesAddAction);

  blockagesCmd
    .command("resolve <blockedId>")
    .description("Resolve blockage dependencies")
    .requiredOption("--by <ids...>", "Blocker issue IDs to resolve")
    .action(blockagesResolveAction);

  blockagesCmd
    .command("delete <blockedId>")
    .description("Delete blockage dependencies")
    .requiredOption("--by <ids...>", "Blocker issue IDs to delete")
    .action(blockagesDeleteAction);

  blockagesCmd
    .command("list <issueId>")
    .description("List blockage info for an issue")
    .action(blockagesListAction);

  return program;
}

