1	import { existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
2	import { execFileSync } from "node:child_process";
3	import { join, normalize, resolve } from "node:path";
4	import type { WorktreeInitResult, WorktreePullResult, WorktreeSyncResult } from "../types";
5	import { AgentrackError, ErrorCodes } from "./errors";
6	
7	/** Branch name used for the agentrack data worktree. */
8	export const WORKTREE_BRANCH = "_agentrack";
9	
10	/** Directory name for the agentrack data worktree. */
11	export const WORKTREE_DIR = ".agentrack";
12	
13	/**
14	 * Default file contents for the orphan branch.
15	 * These match the Tracker.init() defaults exactly.
16	 */
17	const DEFAULT_CONFIG = { auth: { mode: "open", defaultUser: "anonymous" } };
18	const DEFAULT_INDEX = { open: [], closed: [], childrenOf: {} };
19	const DEFAULT_DEPENDENCIES = { blockedBy: {}, blocks: {} };
20	const DEFAULT_USERS = { users: [] };
21	
22	// ─── Git helpers ─────────────────────────────────────────────────────
23	
24	/**
25	 * Execute a git command synchronously using array-based argument passing.
26	 * Uses execFileSync to avoid shell injection.
27	 */
28	function gitExec(cwd: string, args: string[]): string {
29	  return execFileSync("git", args, { cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
30	}
31	
32	/**
33	 * Extract stderr from an execFileSync error.
34	 */
35	function getGitError(err: unknown): string {
36	  if (typeof err === "object" && err !== null && "stderr" in err) {
37	    const stderr = (err as { stderr: unknown }).stderr;
38	    if (typeof stderr === "string") return stderr;
39	  }
40	  return (err as Error).message || String(err);
41	}
42	
43	/**
44	 * Check if `cwd` is inside a git repository.
45	 */
46	function isGitRepo(cwd: string): boolean {
47	  try {
48	    gitExec(cwd, ["rev-parse", "--git-dir"]);
49	    return true;
50	  } catch {
51	    return false;
52	  }
53	}
54	
55	/**
56	 * Get the current branch name.
57	 */
58	function getCurrentBranch(cwd: string): string {
59	  return gitExec(cwd, ["rev-parse", "--abbrev-ref", "HEAD"]).trim();
60	}
61	
62	/**
63	 * Check if a remote named 'origin' is configured.
64	 */
65	function hasRemote(cwd: string): boolean {
66	  try {
67	    const remotes = gitExec(cwd, ["remote"]);
68	    return remotes.split("\n").some((r) => r.trim() === "origin");
69	  } catch {
70	    return false;
71	  }
72	}
73	
74	/**
75	 * Create a blob object from content via stdin.
76	 * Returns the blob hash.
77	 */
78	function gitHashObject(cwd: string, content: string): string {
79	  // execFileSync supports Buffer input via input option
80	  return execFileSync("git", ["hash-object", "-w", "--stdin"], {
81	    cwd,
82	    encoding: "utf-8",
83	    input: content,
84	    stdio: ["pipe", "pipe", "pipe"],
85	  }).trim();
86	}
87	
88	/**
89	 * Create a tree object from formatted entries.
90	 */
91	function gitMkTree(cwd: string, entries: string): string {
92	  return execFileSync("git", ["mktree"], {
93	    cwd,
94	    encoding: "utf-8",
95	    input: entries,
96	    stdio: ["pipe", "pipe", "pipe"],
97	  }).trim();
98	}
99	
100	/**
101	 * Create a commit from a tree hash.
102	 */
103	function gitCommitTree(cwd: string, tree: string, message: string): string {
104	  return execFileSync("git", ["commit-tree", tree, "-m", message], {
105	    cwd,
106	    encoding: "utf-8",
107	    stdio: ["pipe", "pipe", "pipe"],
108	  }).trim();
109	}
110	
111	// ─── Gitignore helpers ───────────────────────────────────────────────
112	
113	/**
114	 * Check if the gitignore content already has an entry for .agentrack.
115	 * Matches common patterns: /.agentrack/, .agentrack/, /.agentrack, .agentrack
116	 */
117	function gitignoreHasEntry(content: string): boolean {
118	  return content.split("\n").some((rawLine) => {
119	    const line = rawLine.trim();
120	    // Skip comments and empty lines
121	    if (!line || line.startsWith("#")) return false;
122	    return (
123	      line === "/.agentrack/" ||
124	      line === ".agentrack/" ||
125	      line === "/.agentrack" ||
126	      line === ".agentrack"
127	    );
128	  });
129	}
130	
131	/**
132	 * Ensure .gitignore has an entry for .agentrack.
133	 * Appends the entry if missing. Does NOT stage or commit.
134	 * Returns true if an entry was added.
135	 */
136	function ensureGitignoreEntry(cwd: string): boolean {
137	  const gitignorePath = join(cwd, ".gitignore");
138	  if (existsSync(gitignorePath)) {
139	    const content = readFileSync(gitignorePath, "utf-8");
140	    if (gitignoreHasEntry(content)) {
141	      return false;
142	    }
143	    // Append entry (ensure newline before if file doesn't end with one)
144	    const suffix = content.endsWith("\n") ? "" : "\n";
145	    writeFileSync(gitignorePath, `${content}${suffix}/.agentrack/\n`, "utf-8");
146	  } else {
147	    writeFileSync(gitignorePath, "/.agentrack/\n", "utf-8");
148	  }
149	  return true;
150	}
151	
152	// ─── Precondition checks ─────────────────────────────────────────────
153	
154	/**
155	 * Validate preconditions before worktree initialization.
156	 * Throws AgentrackError if any precondition fails.
157	 */
158	function checkPreconditions(cwd: string): void {
159	  // Must be inside a git repo
160	  if (!isGitRepo(cwd)) {
161	    throw new AgentrackError(
162	      ErrorCodes.NOT_A_GIT_REPO.result,
163	      "Not inside a git repository",
164	      ErrorCodes.NOT_A_GIT_REPO.exitCode,
165	    );
166	  }
167	
168	  // .agentrack must not exist as a non-worktree (legacy)
169	  const agentrackPath = join(cwd, WORKTREE_DIR);
170	  if (existsSync(agentrackPath)) {
171	    const stat = statSync(agentrackPath);
172	    if (!stat.isDirectory()) {
173	      throw new AgentrackError(
174	        ErrorCodes.MIGRATION_REQUIRED.result,
175	        ".agentrack exists but is not a directory. Remove it and re-run init.",
176	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
177	      );
178	    }
179	    // Directory exists — if not a worktree, it's a legacy directory
180	    if (!isWorktreeInitialized(cwd)) {
181	      throw new AgentrackError(
182	        ErrorCodes.MIGRATION_REQUIRED.result,
183	        ".agentrack/ exists but is not a git worktree. Remove it manually and re-run init.",
184	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
185	      );
186	    }
187	    // If it IS a valid worktree, caller should handle ALREADY_INITIALIZED
188	  }
189	
190	  // Must not be on the _agentrack branch
191	  const currentBranch = getCurrentBranch(cwd);
192	  if (currentBranch === WORKTREE_BRANCH) {
193	    throw new AgentrackError(
194	      ErrorCodes.INVALID_STATE.result,
195	      "Cannot init: currently on the _agentrack branch. Switch to a code branch first.",
196	      ErrorCodes.INVALID_STATE.exitCode,
197	    );
198	  }
199	}
200	
201	// ─── Public API ──────────────────────────────────────────────────────
202	
203	/**
204	 * Detect which init scenario applies: 'fresh' (no remote branch) or 'join' (remote branch exists).
205	 */
206	export function detectInitScenario(cwd: string): "fresh" | "join" {
207	  try {
208	    const result = gitExec(cwd, ["ls-remote", "--heads", "origin", WORKTREE_BRANCH]);
209	    return result.trim().length > 0 ? "join" : "fresh";
210	  } catch {
211	    // No remote or no connectivity → fresh
212	    return "fresh";
213	  }
214	}
215	
216	/**
217	 * Check if .agentrack/ is a valid git worktree for the _agentrack branch.
218	 */
219	export function isWorktreeInitialized(cwd: string): boolean {
220	  try {
221	    const worktreeList = gitExec(cwd, ["worktree", "list", "--porcelain"]);
222	    const normalizedCwd = resolve(cwd);
223	    const expectedPath = normalize(join(normalizedCwd, WORKTREE_DIR));
224	
225	    return worktreeList.split("\n").some((line) => {
226	      if (!line.startsWith("worktree ")) return false;
227	      const wtPath = line.slice("worktree ".length);
228	      return normalize(wtPath) === expectedPath;
229	    });
230	  } catch {
231	    return false;
232	  }
233	}
234	
235	/**
236	 * Scenario A: create orphan branch with initial data, push, mount worktree.
237	 * Uses git plumbing commands to avoid modifying the working tree.
238	 */
239	export function initFreshWorktree(cwd: string): WorktreeInitResult {
240	  // 1. Create blob objects for initial files
241	  const configBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_CONFIG, null, 2)}\n`);
242	  const indexBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_INDEX, null, 2)}\n`);
243	  const depsBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_DEPENDENCIES, null, 2)}\n`);
244	  const usersBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_USERS, null, 2)}\n`);
245	
246	  // 2. Create a tree object referencing these blobs
247	  const treeInput = [
248	    `100644 blob ${configBlob}\tconfig.json`,
249	    `100644 blob ${indexBlob}\tindex.json`,
250	    `100644 blob ${depsBlob}\tdependencies.json`,
251	    `100644 blob ${usersBlob}\tusers.json`,
252	  ].join("\n");
253	  const tree = gitMkTree(cwd, treeInput);
254	
255	  // 3. Create a commit from the tree
256	  const commit = gitCommitTree(cwd, tree, "init _agentrack branch");
257	
258	  // 4. Create the _agentrack branch ref
259	  try {
260	    gitExec(cwd, ["branch", WORKTREE_BRANCH, commit]);
261	  } catch (err) {
262	    // Branch might already exist from a failed previous attempt
263	    const stderr = getGitError(err);
264	    if (stderr.includes("already exists")) {
265	      // Force-update the branch to our new commit
266	      gitExec(cwd, ["branch", "-f", WORKTREE_BRANCH, commit]);
267	    } else {
268	      throw new AgentrackError(
269	        ErrorCodes.INVALID_STATE.result,
270	        `Failed to create branch: ${stderr}`,
271	        ErrorCodes.INVALID_STATE.exitCode,
272	      );
273	    }
274	  }
275	
276	  // 5. Push to remote (if available)
277	  if (hasRemote(cwd)) {
278	    try {
279	      gitExec(cwd, ["push", "-u", "origin", WORKTREE_BRANCH]);
280	    } catch (pushErr) {
281	      const stderr = getGitError(pushErr);
282	      // If push fails because branch already exists remotely, fall back to join
283	      if (
284	        stderr.includes("already exists") ||
285	        stderr.includes("failed to push") ||
286	        stderr.includes("non-fast-forward")
287	      ) {
288	        return initJoinWorktree(cwd);
289	      }
290	      // Network or other errors — proceed with local branch only (warn implicitly)
291	    }
292	  }
293	
294	  // 6. Ensure .gitignore entry
295	  ensureGitignoreEntry(cwd);
296	
297	  // 7. Mount worktree
298	  try {
299	    gitExec(cwd, ["worktree", "add", WORKTREE_DIR, WORKTREE_BRANCH]);
300	  } catch (err) {
301	    const stderr = getGitError(err);
302	    throw new AgentrackError(
303	      ErrorCodes.INVALID_STATE.result,
304	      `Failed to mount worktree: ${stderr}`,
305	      ErrorCodes.INVALID_STATE.exitCode,
306	    );
307	  }
308	
309	  return { scenario: "fresh", path: resolve(cwd, WORKTREE_DIR) };
310	}
311	
312	/**
313	 * Scenario B: fetch remote branch, create tracking branch, mount worktree.
314	 */
315	export function initJoinWorktree(cwd: string): WorktreeInitResult {
316	  // 1. Fetch the remote branch
317	  try {
318	    gitExec(cwd, ["fetch", "origin", WORKTREE_BRANCH]);
319	  } catch (err) {
320	    const stderr = getGitError(err);
321	    throw new AgentrackError(
322	      ErrorCodes.INVALID_STATE.result,
323	      `Failed to fetch remote branch: ${stderr}`,
324	      ErrorCodes.INVALID_STATE.exitCode,
325	    );
326	  }
327	
328	  // 2. Create local tracking branch
329	  try {
330	    gitExec(cwd, ["branch", WORKTREE_BRANCH, `origin/${WORKTREE_BRANCH}`]);
331	  } catch {
332	    // Branch might already exist — force-update to remote ref
333	    try {
334	      gitExec(cwd, ["branch", "-f", WORKTREE_BRANCH, `origin/${WORKTREE_BRANCH}`]);
335	    } catch (err) {
336	      const stderr = getGitError(err);
337	      throw new AgentrackError(
338	        ErrorCodes.INVALID_STATE.result,
339	        `Failed to create tracking branch: ${stderr}`,
340	        ErrorCodes.INVALID_STATE.exitCode,
341	      );
342	    }
343	  }
344	
345	  // 3. Ensure .gitignore entry
346	  ensureGitignoreEntry(cwd);
347	
348	  // 4. Mount worktree
349	  try {
350	    gitExec(cwd, ["worktree", "add", WORKTREE_DIR, WORKTREE_BRANCH]);
351	  } catch (err) {
352	    const stderr = getGitError(err);
353	    throw new AgentrackError(
354	      ErrorCodes.INVALID_STATE.result,
355	      `Failed to mount worktree: ${stderr}`,
356	      ErrorCodes.INVALID_STATE.exitCode,
357	    );
358	  }
359	
360	  return { scenario: "join", path: resolve(cwd, WORKTREE_DIR) };
361	}
362	
363	/**
364	 * Initialize the agentrack worktree. Performs precondition checks, detects the
365	 * scenario, and delegates to the appropriate setup function.
366	 *
367	 * Returns the init result, or throws AgentrackError on failure.
368	 */
369	export function initWorktree(cwd: string): WorktreeInitResult {
370	  // Check if already initialized
371	  if (isWorktreeInitialized(cwd)) {
372	    return { scenario: "already_initialized", path: resolve(cwd, WORKTREE_DIR) };
373	  }
374	
375	  // Validate preconditions (throws on failure)
376	  checkPreconditions(cwd);
377	
378	  // Detect scenario and delegate
379	  const scenario = detectInitScenario(cwd);
380	  if (scenario === "fresh") {
381	    return initFreshWorktree(cwd);
382	  }
383	  return initJoinWorktree(cwd);
384	}
385	
386	/**
387	 * Stage and commit .gitignore changes on the current code branch.
388	 * Used after initWorktree() to persist the .agentrack/ gitignore entry.
389	 * No-op if there are no changes to commit.
390	 */
391	export function commitGitignoreChange(cwd: string): void {
392	  try {
393	    gitExec(cwd, ["add", ".gitignore"]);
394	    gitExec(cwd, ["commit", "-m", "chore: add .agentrack/ to .gitignore"]);
395	  } catch {
396	    // No changes to commit or .gitignore unchanged
397	  }
398	}
399	
400	/**
401	 * Stage all changes in the worktree and commit them with the given message.
402	 * Used after tracker.init() to persist initial data to the _agentrack branch.
403	 */
404	export function commitWorktreeData(cwd: string, message: string): void {
405	  const worktreeDir = join(cwd, WORKTREE_DIR);
406	  gitExec(worktreeDir, ["add", "-A"]);
407	  try {
408	    gitExec(worktreeDir, ["commit", "-m", message]);
409	  } catch {
410	    // No changes to commit — that's fine (e.g., data already committed)
411	  }
412	}
413	
414	/**
415	 * Stage all changes, auto-commit, and push to remote.
416	 */
417	export function pushWorktree(cwd: string, message?: string): WorktreeSyncResult {
418	  const worktreeDir = join(cwd, WORKTREE_DIR);
419	
420	  // Verify worktree is initialized
421	  if (!isWorktreeInitialized(cwd)) {
422	    throw new AgentrackError(
423	      ErrorCodes.NOT_INITIALIZED.result,
424	      "Agentrack not initialized. Run `agt init` first.",
425	      ErrorCodes.NOT_INITIALIZED.exitCode,
426	    );
427	  }
428	
429	  // Stage all changes
430	  gitExec(worktreeDir, ["add", "-A"]);
431	
432	  // Check for staged changes
433	  let hasStagedChanges = false;
434	  try {
435	    gitExec(worktreeDir, ["diff", "--cached", "--quiet"]);
436	    // Exit code 0 = no diff = no staged changes
437	  } catch {
438	    // Exit code 1 = there are staged changes
439	    hasStagedChanges = true;
440	  }
441	
442	  if (hasStagedChanges) {
443	    // Commit staged changes
444	    const commitMessage =
445	      message || `sync: ${new Date().toISOString()}`;
446	    try {
447	      gitExec(worktreeDir, ["commit", "-m", commitMessage]);
448	    } catch (err) {
449	      const stderr = getGitError(err);
450	      throw new AgentrackError(
451	        ErrorCodes.PUSH_FAILED.result,
452	        `git commit failed: ${stderr}`,
453	        ErrorCodes.PUSH_FAILED.exitCode,
454	      );
455	    }
456	  }
457	
458	  // Check if there's anything to push
459	  let hasUnpushedCommits = false;
460	  try {
461	    const count = gitExec(worktreeDir, ["rev-list", "--count", "@{upstream}..HEAD"]).trim();
462	    hasUnpushedCommits = parseInt(count, 10) > 0;
463	  } catch {
464	    // No upstream set — means we need to push
465	    hasUnpushedCommits = true;
466	  }
467	
468	  if (!hasStagedChanges && !hasUnpushedCommits) {
469	    return { synced: false, message: "No changes to sync" };
470	  }
471	
472	  // Push to remote
473	  if (hasRemote(cwd)) {
474	    try {
475	      gitExec(worktreeDir, ["push"]);
476	    } catch (err) {
477	      const stderr = getGitError(err);
478	      throw new AgentrackError(
479	        ErrorCodes.PUSH_FAILED.result,
480	        `git push failed: ${stderr}`,
481	        ErrorCodes.PUSH_FAILED.exitCode,
482	      );
483	    }
484	  }
485	
486	  return {
487	    synced: true,
488	    commitCount: hasStagedChanges ? 1 : 0,
489	  };
490	}
491	
492	/**
493	 * Pull latest from remote into the worktree.
494	 */
495	export function pullWorktree(cwd: string): WorktreePullResult {
496	  const worktreeDir = join(cwd, WORKTREE_DIR);
497	
498	  // Verify worktree is initialized
499	  if (!isWorktreeInitialized(cwd)) {
500	    throw new AgentrackError(
501	      ErrorCodes.NOT_INITIALIZED.result,
502	      "Agentrack not initialized. Run `agt init` first.",
503	      ErrorCodes.NOT_INITIALIZED.exitCode,
504	    );
505	  }
506	
507	  try {
508	    const output = gitExec(worktreeDir, ["pull"]);
509	    // "Already up to date." means no updates
510	    const updated = !output.includes("Already up to date");
511	    return { updated };
512	  } catch (err) {
513	    const stderr = getGitError(err);
514	    throw new AgentrackError(
515	      ErrorCodes.PULL_FAILED.result,
516	      `git pull failed: ${stderr}`,
517	      ErrorCodes.PULL_FAILED.exitCode,
518	    );
519	  }
520	}
